-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 notable NPCs are in' AS assertion, count(*) AS got, 4 AS want
  FROM notable_npcs WHERE slug IN ('king-arrthuu', 'sir-prrcyvel', 'sir-dred', 'sir-galahad');
SELECT 'and the notables 30' AS assertion, count(*) AS got, 30 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('king-arrthuu', 'sir-prrcyvel', 'sir-dred', 'sir-galahad');

