INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('king-arrthuu', 'King Arr''thuu', 'Arr''thuu of the Southern Forests (pronounced Are thew)', 'King of New Camelot', 'rifts', 'Human (his block prints no race line; the text calls him a possible descendant of pre-Rifts British psychic agents)', '6th level Royal Knight and psionic (as printed)', 6, 'Scrupulous', '22', '6 feet, 2 inches (1.9 m)', '180 lbs (81 kg)', '{"IQ":11,"ME":20,"MA":24,"PS":21,"PP":20,"PE":19,"PB":18,"Spd":19}', 43, 58, NULL, 15, 75, NULL, 11, '{"attacks":4,"initiative":1,"strike":5,"parry":8,"dodge":8,"damage":6,"roll":3,"pull":3}', 'Hand to hand: expert, four attacks per melee. +6 S.D.C. damage; kick does 1D6; critical strike on a natural 18-20. +3 to save vs psionic attack, +2 vs magic, +2 vs poison, +2 vs Horror Factor. 80% to evoke trust or intimidation, 40% to charm and impress. His Horror Factor of 11 applies to monsters and evildoers.', '[]', 'No percentages printed; all at sixth level: Hand to Hand: Expert, Boxing, W.P. Sword, W.P. Knife, W.P. Blunt, W.P. Energy Rifle, Land Navigation, Wilderness Survival, Horsemanship, Pilot Hover Vehicle, Radio: Basic, Mathematics: Basic, and speaks English/American, Euro, Gobblely and Dragonese. Reads English only at fourth level proficiency.', 'Can wield Caliber X: the weapon is keyed to a narrow psychic wavelength that perhaps one person in ten million shares, and it is attuned to him. He can sense where it lies within 200 miles (320 km), much as a dowser would.', 'No spell casting. Recognizes real wards, runes and mystic symbols though he cannot read them; 12% chance, +2% per level after the first, to identify a specific ward.', '75 I.S.P., 6th level: Ectoplasm, Impervious to Cold, Impervious to Fire, Mind Block, Nightvision, Resist Fatigue, Summon Inner Strength and Telekinesis.', NULL, 'None.', 'Caliber X, always at his side. A silver dagger (he always carries one, and favors knives), a wooden cross a druid gave him, a plasma lance (printed only as plasma lance; the Nexus Knight Plasma Lance is the catalog row of that name), TX-22 Precision Laser Pistol (printed as Triax laser pistol: 2D4 M.D., 20 shots, 1000 ft), TX-30 Triax Ion Pulse Rifle (printed as Triax ion pulse rifle), JA-9 Juicer Assassin Variable Laser Rifle (printed as JA-9 variable rifle, 2D6 M.D.) and a TW Flaming Sword (4D6 M.D.). As king he can call on many more weapons and magic items. Body armor: environmental plate armor, 100 M.D.C., 20 lbs (9 kg), fair mobility, -10% to prowl. Vehicle: a robot horse Mrrlyn named Morgana.', 'Usually 50,000 credits and 2D6x1000 in gold or gems, with reasonable access to a kingdom treasury of about 200 million. His basic armor, weapons and needs are provided, and he can muster the Knights of Camelot, half the Rival Cavaliers and 1D4x100 other fighters at a moment''s notice.', 'Brave to the point of recklessness, which worries Mrrlyn: he insists on riding into battle beside his knights rather than ruling from a tower. Compassionate toward every intelligent being, merciful in combat and true to the code of chivalry; quick to learn, imaginative and open minded despite his youth. He trusts Mrrlyn as a father and loves Guinevere, and would be shattered to learn what they really are.', 'Mrrlyn, whom he trusts completely; his knights, Sir Prrcyvel above all, his closest friend; Lady Guinevere; his people. He hopes for alliances with kingdoms that share Camelot''s ideals and would welcome one with the New German Republic.', 'The demons and monsters that hold most of Europe.', 'The young king Mrrlyn found and groomed into a hero of legend. He took the throne at 16 after King Ebor and his two sons were killed by demons, and has ruled six years since. Mrrlyn staged a version of the Excalibur legend to prove his claim: the Lady of the Lake named him the true king and gave him Caliber X. He means to propose to Guinevere within 4D4 months. Caliber X is its own catalog row (p.104-107)', 'Rifts World Book 3: England p.104-107'),
('sir-prrcyvel', 'Sir Prrcyvel', 'Ro Ven', 'Knight of New Camelot, the King''s best friend', 'rifts', 'Chiang-Ku dragon, metamorphosed into human form', '9th level Tattoo Master (Chiang-Ku R.C.C.)', 9, 'Scrupulous', NULL, '6 feet, 2 inches in human form', NULL, '{"IQ":21,"ME":20,"MA":29,"PS":26,"PP":19,"PE":19,"PB":17,"Spd":22}', NULL, NULL, 900, 700, 80, NULL, 13, '{"attacks":5,"strike":3,"parry":5,"dodge":5,"damage":6,"roll":4,"pull":4}', 'Adult figures. M.D.C. 900 in human form, 1900 in his natural serpent form. Five attacks per melee by hand to hand, tattoo magic or psionics; hand to hand: expert. Critical strike on an unmodified 18-20; paired weapons. +1 to save vs psionics, +3 vs spell and illusionary magic, +1 vs circle magic, +6 vs Horror Factor. His tattoos add +1 to save vs all magic, +2 vs Horror Factor and +2 to P.E., and he recovers P.P.E. twice as fast.', '[{"name":"Mathematics: Basic","pct":98},{"name":"Art","pct":92},{"name":"Land Navigation","pct":75},{"name":"Wilderness Survival","pct":77},{"name":"Streetwise","pct":59},{"name":"Disguise","pct":72},{"name":"Holistic Medicine","pct":72},{"name":"Climbing","pct":97},{"name":"Lore: Faeries & Creatures of Magic","pct":92},{"name":"Lore: Demons & Monsters","pct":77},{"name":"Horsemanship: General","pct":84},{"name":"Hover Craft (ground)","pct":98}]', 'R.C.C. skills, the I.Q. bonus of +7% included. All domestic skills at about 82%. The book prints faerie lore and hovercraft. Weapon skills: W.P. Knife, Sword, Chain, Automatic Rifle, Energy Pistol and Energy Rifle. Hand to Hand: Expert.', 'Nightvision 90 ft (27.4 m); impervious to poison, toxins, drugs and gases; sees the invisible; fire and cold do him half damage; bio-regenerates 1D6x5 M.D. every five minutes. Metamorphosis as any Chiang-Ku dragon, which is how he passes as a human knight.', 'A full understanding of magic, complete knowledge of tattoo magic, and the making of the Elixir of Power and Deceit. As a Chiang-Ku Tattoo Master he bears the Marks of Heritage and these tattoos. Powers: Chain Encircling a Skull (+3 to save vs psionics); Chain with a Broken Link (+6 to strength for 45 minutes); Eye of Mystic Knowledge (reads magic symbols and runes); Heart with Tiny Wings (runs at 110 mph, 176 km). Animals and monsters: ferret, horse (rideable), gryphon (rideable), manticore, giant spider. Simple weapons: silver knife (1D4 S.D.C.), broadsword (1D8 S.D.C.). Magic weapons: flaming shield (indestructible, +2 to parry); flaming knife and broadsword crossed (1D4 M.D. and 1D8 M.D., both +1 to strike and +2 to parry); flaming mace and chain with a coiled serpent (2D6 M.D., 4D6 against dragons and serpents).', 'Major psionic, 80 I.S.P.: Astral Projection, Clairvoyance, Empathy, Mind Block, Presence Sense, See Aura, Sense Evil, Sense Magic, Death Trance, Levitation and Summon Inner Strength.', NULL, NULL, 'A matched knife and broadsword, a mace and chain, a Wilk''s 320 Laser Pistol (1D6 M.D., 20 shots) and a TX-30 Triax Ion Pulse Rifle (printed as Triax ion pulse rifle) with a 50-shot E-clip. Body armor: crusader style, 55 M.D.C. Vehicle: a bionic horse.', 'Seldom more than 2D6x1000 credits; most of it goes to the poor.', 'Brave and devoted to the king, guarded and tactful at court. He never openly criticizes Mrrlyn, offering other views instead, and refuses to manipulate Arr''thuu himself: he wants the king to be his own man. Feigns friendship with Sir Dred to watch Mrrlyn through him.', 'King Arr''thuu, his sworn friend; his squire Almartin, a 2nd level Undead Slayer made by one of the Nog Henge serpents; the Nog Henge druids, who are Chiang-Ku in disguise, and whom he secretly keeps informed.', 'Mrrlyn, whom he alone among the knights knows to be part of an alien intelligence; he does not know that Guinevere and the Lady of the Lake are too. Mrrlyn and Guinevere suspect some hidden mage is spying on the enchanter, but not that it is him.', 'One of New Camelot''s bravest and most honored knights, and in secret a Chiang-Ku dragon in human shape (pronounced Pur-seh-val). He and the king have been close as brothers for five years, and many take him for the royal bodyguard. Arr''thuu suspects there is more to him and guesses he is a True Atlantean. He fears Mrrlyn means to use Guinevere to tighten his grip on the king, and is likely to say the wrong thing to her one day. In human form he has shoulder-length dark brown hair and blue eyes, and dresses stylishly with a cape and a plumed, wide-brimmed hat (p.107-108)', 'Rifts World Book 3: England p.107-108'),
('sir-dred', 'Sir Dred', 'Andrew Winford', 'Knight of Camelot, the youngest ever made', 'rifts', 'Human (his block prints no race line)', '3rd level Royal Knight', 3, 'Anarchist', '19', '6 feet (1.8 m)', '160 lbs (72 kg)', '{"IQ":15,"ME":14,"MA":18,"PS":24,"PP":21,"PE":21,"PB":15,"Spd":26}', 31, 64, NULL, 10, NULL, NULL, NULL, '{"attacks":3,"initiative":1,"strike":5,"parry":6,"dodge":6,"damage":9,"roll":4,"pull":4}', 'Hand to hand: martial arts and boxing, three attacks per melee. +9 S.D.C. damage; karate kick does 1D8; pin/incapacitate on a natural 18-20. +3 to save vs magic, +3 vs poison, +2 vs Horror Factor. 50% to evoke trust or intimidation. I.S.P.: none.', '[]', 'No percentages printed; the book says all at sixth level although he is third: Hand to Hand: Martial Arts, W.P. Sword, W.P. Knife, W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy Energy Weapons (printed as energy heavy), Land Navigation, Wilderness Survival, Horsemanship, Pilot Hover Vehicle, Radio: Basic, Play Musical Instrument: Guitar, Dance, Mathematics: Basic, and speaks English/American, Euro and Gobblely.', NULL, 'None of his own. Mrrlyn gave him a corrupted wand holding four spells: Chameleon, Armor of Ithan, Levitation and Turn Dead; six castings in any 24 hours, all at fourth level strength.', 'None.', NULL, 'Oxygen storage cell (30 minutes), gyro-compass, radiation detector, universal head jack and sound filtration system.', 'A silver dagger, a silver cross, a TX-22 Precision Laser Pistol (printed as Triax laser pistol: 2D4 M.D., 20 shots, 1000 ft), a Triax particle beam rifle (as printed: 1D6x10 M.D., 1400 ft; no catalog row carries those figures), a TX-5 Triax Pump Pistol (4D6 M.D.) and a TX-500 Triax Borg Rail Gun (6D6 M.D. a burst, 13 bursts). Mrrlyn''s corrupted wand. Body armor: environmental plate armor, 90 M.D.C., 18 lbs (8 kg), fair mobility, -10% to prowl. Vehicles: two hovercycles and a jet pack.', '50,000 credits and 6000 in gold, and he can raise 100,000 more in a few days. His wealthy family, of royal descent, keeps him in fine clothes, weapons, implants and gear; their estate is worth about five million credits.', 'Arrogant, boastful and envious: he covets Galahad''s fame and the king''s power, and whines to Mrrlyn when slighted. Not wicked yet, and he has the makings of a noble knight, but Mrrlyn''s favors are bending him, and if the other knights keep shunning him he will grow steadily more evil.', 'Mrrlyn, the nexus knights, his fellow Knights of Camelot, his country and his king, in that order of loyalty. He thinks Sir Prrcyvel his one true friend, but Prrcyvel only uses him to watch Mrrlyn.', 'None named; most knights treat him with scorn, and he resents Galahad and the king for the kindness they offer.', 'The youngest Knight of Camelot, knighted for defending a village against demons and for apparently saving Mrrlyn by taking an enemy barrage meant for the enchanter; Mrrlyn healed him. Mrrlyn now feeds him small favors and confidences, and Dred unwittingly reports the other knights'' talk and petty failings back to him (p.108-109)', 'Rifts World Book 3: England p.108-109'),
('sir-galahad', 'Sir Galahad', 'Argo Vinuh of the Bagh-Dach Clan', 'Knight of Camelot, champion of New Camelot', 'rifts', 'True Atlantean', '9th level Undead Slayer', 9, 'Principled', '211, looks about 28', '6 feet, 9 inches (2 m)', '220 lbs (99 kg)', '{"IQ":13,"ME":23,"MA":20,"PS":22,"PP":21,"PE":18,"PB":17,"Spd":30}', NULL, NULL, 337, 322, NULL, NULL, 13, '{"attacks":5,"initiative":1,"strike":5,"parry":6,"dodge":6,"damage":7,"roll":4,"pull":4}', 'Bonuses include attributes, tattoos and hand to hand: martial arts and boxing. Five attacks per melee by hand to hand or tattoo magic. The +7 damage is M.D. Critical strike on an unmodified 18-20; karate kick (1D6), jump kick (critical strike), leap attack, entangle and paired weapons. +5 to save vs psionics, +6 vs all magic, +8 vs Horror Factor; 60% to evoke trust or intimidation. Supernatural P.S. and P.E.; a mega-damage being. His Horror Factor of 13 applies to monsters and practitioners of evil. I.S.P.: none.', '[{"name":"Mathematics: Basic","pct":98},{"name":"Language: Atlantean","pct":98},{"name":"Literacy: Atlantean","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Language: Faerie Speak","pct":98},{"name":"Language: Dragonese/Elven","pct":98},{"name":"Intelligence","pct":98},{"name":"Land Navigation","pct":98},{"name":"Wilderness Survival","pct":98},{"name":"Disguise","pct":98},{"name":"First Aid","pct":98},{"name":"Lore: Faeries & Creatures of Magic","pct":98},{"name":"Lore: Demons & Monsters","pct":98},{"name":"Horsemanship: General","pct":98},{"name":"Hover Craft (ground)","pct":98},{"name":"Climbing","pct":98},{"name":"Swimming","pct":98},{"name":"Prowl","pct":75}]', 'The book prints faerie lore, pilot hovercraft and Dragonese/elf. Weapon skills: Paired Weapons, W.P. Archery & Targeting, W.P. Knife, W.P. Sword, W.P. Axe (+1 to strike and parry at levels 2, 6, 12 and 15), W.P. Energy Pistol and W.P. Energy Rifle. Hand to Hand: Martial Arts and Boxing.', 'A supernatural, mega-damage being with superhuman strength and endurance. Recovers P.P.E. at 20 points an hour. Cannot be metamorphosed or transformed by any means; vampire bites cannot harm him. Senses vampires within 1000 ft (305 m) and knows one on sight (98%). Senses ley lines and rifts as a Ley Line Walker does, can phase along ley lines, and can operate dimensional pyramids.', 'Understands magic tattoos and their use. Bears the Marks of Heritage plus 30 tattoos (32 in all). Animals and monsters: bear, horse (rideable), dragondactyl (rideable), melech (rideable). Simple weapons: silver knife (1D4 S.D.C.), four wooden arrows, short sword (1D8 S.D.C.), broadsword (1D8 S.D.C.), wooden throwing stick (1D6 S.D.C.). Magic weapons: flaming shield (indestructible, +2 to parry); winged flaming broadsword encoiled by a serpent (three tattoos; 2D6 M.D., 4D6 against dragons and serpents, returns when thrown); bow with two sets of four winged flaming arrows (2D6 M.D., triple range, magically return); crossed flaming battle axes dripping blood (three tattoos; 4D6 M.D., +1 to strike, +2 to parry). Power tattoos: Turn Dead (silver cross), Protection from Vampires (heart impaled by a stake), Impervious to Mind Control (skull in chains), Invulnerability, 675 M.D.C. (heart in chains), Control the Forces of Air (cloud in chains), Healing: Basic (pink rose), Healing: Super (phoenix), Protection from Poison, impervious to poison and +2 to save vs drugs and gases (ball of thorns), Supernatural Vision: see the invisible, nightvision 1200 ft (366 m), see aura, +1 to strike and initiative (three eyes), Knowledge and Reading (an eye), Blind by Touch (an eye with a dagger in it), and Shoot Lightning for up to 9 minutes (lightning bolt).', 'None.', NULL, NULL, 'His block lists only his tattoo weapons; no gear, body armor, vehicle or money is printed for him.', NULL, 'Honest, loyal, compassionate and merciful in combat, and a relentless fighter against the supernatural. He keeps an eye on Mrrlyn, worried the enchanter will make a puppet of the king, and grows more certain Mrrlyn is not human, but he shares that with nobody. One of the few knights who treats Sir Dred kindly.', 'King Arr''thuu, his friend; his fellow Knights of Camelot.', 'Vampires and the supernatural. He has fought minions of the Zllyphan before without yet seeing that old foe in Mrrlyn.', 'An Atlantean Undead Slayer and the most celebrated of New Camelot''s champions, his exploits spread by Mrrlyn himself. With Sir Prrcyvel he saved King Arr''thuu in a battle the king might otherwise not have survived. A tall, ruggedly handsome man with bronze, tattooed skin and a black mohawk (p.109-110)', 'Rifts World Book 3: England p.109-110');
INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
